declare(strict_types=1);

namespace watermossmc\network\mcpe\cache;

/**
 * Static packet cache to avoid re-encoding the same data for every single player.
 * This significantly reduces CPU usage and bandwidth for static data.
 */
final class StaticPacketCache
{
    private static ?self $instance = null;

    /** @var array<string, string> */
    private array $cache = [];

    private function __construct() {}

    public static function getInstance(): self
    {
        if (self::$instance === null) {
            self::$instance = new self();
        }
        return self::$instance;
    }

    public function get(string $key, callable $generator): string
    {
        if (!isset($this->cache[$key])) {
            $this->cache[$key] = $generator();
        }
        return $this->cache[$key];
    }

    public function clear(): void
    {
        $this->cache = [];
    }
}
